// 全冷门先验原付款/货物/文书，再核延期的历史位置；不得向旧账回填今日同意。
#include "task_extension_world.hpp"
#include "resident/kernel/world_bundle.hpp"
namespace hanmo::resident {namespace {
Status enabled(const WorldBundle& w){return w.dynamic_enabled()&&w.catalog->task_extensions&&w.tasks.deadline_extensions?common_success():common_failure("TaskExtensionProfileRequired");}
TaskExtensionHistorySources history(const TaskState& tasks){return {tasks.takeover_execution?&*tasks.takeover_execution:nullptr,tasks.static_assets?&*tasks.static_assets:nullptr,tasks.message_handoffs?&*tasks.message_handoffs:nullptr};}
}
Status validate_task_extension_world(const WorldBundle& w){const auto* state=w.tasks.deadline_extensions?&*w.tasks.deadline_extensions:nullptr;auto valid=validate_task_extension_layout(w.common,w.catalog->identity.module_versions,w.catalog->task_extensions.get(),state);if(!valid.ok)return valid;if(w.catalog->task_extensions){valid=enabled(w);if(!valid.ok)return valid;valid=validate_task_extensions(w.common,w.tasks,*w.catalog->tasks,*w.catalog->interaction,*w.catalog->task_extensions,*state,history(w.tasks));if(!valid.ok)return valid;}return validate_task_extension_cached_results(w.common,state);}
Outcome<TaskExtensionQuote> prepare_task_extension_world(const WorldBundle& w,const StableId& actor,const TaskExtensionCommand& command){auto valid=enabled(w);if(!valid.ok)return {false,{},valid.error};auto access=w.services.interaction_access();return preview_task_extension(w.common,w.tasks,*w.catalog->tasks,w.interaction,*w.catalog->interaction,access,*w.catalog->task_extensions,*w.tasks.deadline_extensions,history(w.tasks),actor,command);}
Outcome<InteractionEffect> commit_task_extension_world(WorldBundle& w,const StableId& actor,const TaskExtensionCommand& command,const TaskExtensionQuote& quote){auto valid=enabled(w);if(!valid.ok)return {false,{},valid.error};if(actor!=quote.consent.meeting.actor_id||command.task_id!=quote.task_id||command.policy_id!=quote.policy_id)return {false,{},common_failure("StaleTaskExtensionQuote").error};auto access=w.services.interaction_access();auto result=commit_task_extension_in_candidate(w.common,w.tasks,*w.catalog->tasks,w.interaction,*w.catalog->interaction,access,*w.catalog->task_extensions,*w.tasks.deadline_extensions,history(w.tasks),quote);if(!result.ok)return {false,{},result.error};InteractionEffect receipt;receipt.settlement_result=result.value;return {true,std::move(receipt),{}};}
Outcome<BoundaryValue> query_task_extension_world(const WorldBundle& w,Integer cursor){auto valid=enabled(w);if(!valid.ok)return {false,{},valid.error};auto access=w.services.interaction_access();return query_task_extensions(w.common,w.tasks,{*w.catalog->common,*w.catalog->tasks,w.interaction,*w.catalog->interaction,access,*w.catalog->task_extensions,*w.tasks.deadline_extensions,history(w.tasks)},cursor);}
BoundaryValue encode_task_extension_quote(const TaskExtensionQuote& quote){using V=BoundaryValue;return boundary::obj({{"duration",V{Integer{0}}},{"task_id",V{quote.task_id}},{"policy_id",V{quote.policy_id}},{"original_deadline_tick",V{quote.original_deadline_tick}},{"deadline_tick",V{quote.deadline_tick}}});}
}
